:"49980000","sexo":"F","rg":"4401497-0","orgao_emissor":"SSP/AL","rg_uf_emissao":"AL","rg_data_emissao":"2018-08-10","tipo_documento":"RG (ANTIGO)","nome_mae":"ELIANE DOS SANTOS CASSEMIRO","nome_pai":"WILTON PEREIRA E SILVA","nacionalidade":"BRASILEIRO (A)","naturalidade":"ARAPIRACA"},{"linha":36,"turma_origem":"ENF T-42 INT","turno_origem":"INTEGRAL","nome":"YASMIM DOS SANTOS OLIVEIRA","cpf":"09706870520","email":"yo672543@gmail.com","telefone":"(79) 99957-9119","data_nascimento":"2001-05-18","data_matricula":null,"endereco":"CONJ. HAB. MANUEL F. CALUMBY","bairro":"CENTRO","cidade":"BREJO GRANDE","uf":"SE","cep":"49995000","sexo":"F","rg":"7.113.451-4","orgao_emissor":"SSP/SE","rg_uf_emissao":"SE","rg_data_emissao":"2016-07-21","tipo_documento":"RG (ANTIGO)","nome_mae":"ALCIONE LOPES DOS SANTOS OLIVEIRA","nome_pai":"ACACIO PINHEIRO DE OLIVEIRA","nacionalidade":"BRASILEIRO (A)","naturalidade":"NEÓPOLIS"}]$source$::jsonb;
  v_turma public.turmas%rowtype;
  v_row record;
  v_parceiro_id uuid;
begin
  if jsonb_array_length(v_source) <> 35 then
    raise exception 'A importação T42 exige exatamente 35 registros de origem.';
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(v_source) as s(cpf text)
    group by cpf
    having count(*) > 1
  ) then
    raise exception 'A origem T42 contém CPF duplicado.';
  end if;

  perform pg_advisory_xact_lock(hashtext('importacao-enf-t42-20260726'));

  select *
  into v_turma
  from public.turmas
  where codigo = 'ENF-T42-INT-MAT'
  for update;

  if not found then
    raise exception 'Turma ENF-T42-INT-MAT não encontrada.';
  end if;

  for v_row in
    select *
    from jsonb_to_recordset(v_source) as s(
      linha integer,
      turma_origem text,
      turno_origem text,
      nome text,
      cpf text,
      email text,
      telefone text,
      data_nascimento date,
      data_matricula date,
      endereco text,
      bairro text,
      cidade text,
      uf text,
      cep text,
      sexo text,
      rg text,
      orgao_emissor text,
      rg_uf_emissao text,
      rg_data_emissao date,
      tipo_documento text,
      nome_mae text,
      nome_pai text,
      nacionalidade text,
      naturalidade text,
      certidao_tipo text,
      certidao_modelo text,
      certidao_matricula text,
      certidao_termo text,
      certidao_livro text,
      certidao_folha text
    )
    order by linha
  loop
    v_parceiro_id := null;

    select p.id
    into v_parceiro_id
    from public.parceiros p
    where regexp_replace(coalesce(p.cpf_cnpj, ''), '\D', '', 'g') = v_row.cpf
    order by p.created_at, p.id
    limit 1;

    if v_parceiro_id is null then
      insert into public.parceiros (
        tipo, nome, cpf_cnpj, email, telefone,
        cep, endereco, bairro, cidade, uf, polo_id,
        status, observacao, data_nascimento, sexo,
        rg, orgao_emissor, rg_data_emissao, nacionalidade, naturalidade,
        nome_mae, nome_pai, rg_uf_emissao, tipo_documento,
        certidao_tipo, certidao_modelo, certidao_matricula,
        certidao_termo, certidao_livro, certidao_folha
      ) values (
        'Aluno', v_row.nome, v_row.cpf, v_row.email, v_row.telefone,
        v_row.cep, v_row.endereco, v_row.bairro, v_row.cidade, v_row.uf, v_turma.polo_id,
        'ATIVO',
        'Importado de turma 42.xls sem criação de usuário Auth, sem envio de e-mail e sem financeiro.',
        v_row.data_nascimento, v_row.sexo,
        v_row.rg, v_row.orgao_emissor, v_row.rg_data_emissao,
        coalesce(v_row.nacionalidade, 'BRASILEIRA'), v_row.naturalidade,
        v_row.nome_mae, v_row.nome_pai, v_row.rg_uf_emissao, v_row.tipo_documento,
        v_row.certidao_tipo, v_row.certidao_modelo, v_row.certidao_matricula,
        v_row.certidao_termo, v_row.certidao_livro, v_row.certidao_folha
      )
      returning id into v_parceiro_id;
    end if;

    if not exists (
      select 1 from public.matriculas m
      where m.aluno_id = v_parceiro_id and m.turma_id = v_turma.id
    ) then
      perform internal_academic.authorize_enrollment_upsert(
        v_parceiro_id, v_turma.id, 'PENDENTE'
      );

      insert into public.matriculas (
        aluno_id, turma_id, status, data_matricula,
        financeiro_herdado, gerar_cobranca_inicial,
        gerar_cobranca_futura, sincronizar_asaas
      ) values (
        v_parceiro_id, v_turma.id, 'PENDENTE',
        coalesce(v_row.data_matricula, v_turma.data_inicio)::timestamp
          at time zone 'America/Maceio',
        false, false, false, false
      );
    end if;
  end loop;

  update public.turmas t
  set vagas_totais = greatest(
    t.vagas_totais,
    (select count(*)::integer from public.matriculas m where m.turma_id = t.id)
  )
  where t.id = v_turma.id;
end;
